+  folders.moveFolderWithin(parent, junk, xray);
+
+  Assert.deepEqual(parent.children, [
+    zulu,
+    junk,
+    xray,
+    inbox,
+    drafts,
+    archives,
+    templates,
+    sent,
+    trash,
+    virtual,
+    unsent,
+    yankee,
